1	/**
2	 * Fake adapters for every port defined in ports.ts.
3	 *
4	 * These are no-I/O, in-memory implementations used in hermetic
5	 * orchestrator-core tests. Each fake records calls so tests can
6	 * assert on what the core invoked without side effects.
7	 */
8	
9	import type {
10	  ExecutorPort,
11	  BriefingTransportPort,
12	  WorkflowStatePort,
13	  CredentialPort,
14	  WorkspacePullPort,
15	  EventEmitterPort,
16	  SchedulerPort,
17	  ClockPort,
18	} from "./ports.js";
19	import type {
20	  ExecutorHandle,
21	  ExecutorPortInput,
22	  ExecutorResult,
23	} from "./types.js";
24	
25	// ── FakeExecutorPort ──────────────────────────────────────────────────────────
26	
27	export interface FakeExecutorPortOpts {
28	  /** Override submit; default generates a deterministic handle from taskId. */
29	  submit?: (input: ExecutorPortInput) => Promise<ExecutorHandle>;
30	  /** Override readResult; default returns { terminal_status: "in_review" }. */
31	  readResult?: (handle: ExecutorHandle) => Promise<ExecutorResult>;
32	}
33	
34	export interface FakeExecutorPort extends ExecutorPort {
35	  /** Handles returned by every submit call, in order. */
36	  readonly submittedHandles: ExecutorHandle[];
37	  /** Inputs received by every submit call, in order. */
38	  readonly submittedInputs: ExecutorPortInput[];
39	}
40	
41	export function createFakeExecutorPort(
42	  opts?: FakeExecutorPortOpts,
43	): FakeExecutorPort {
44	  const submittedHandles: ExecutorHandle[] = [];
45	  const submittedInputs: ExecutorPortInput[] = [];
46	
47	  return {
48	    submittedHandles,
49	    submittedInputs,
50	
51	    async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
52	      if (opts?.submit) {
53	        const h = await opts.submit(input);
54	        submittedHandles.push(h);
55	        submittedInputs.push(input);
56	        return h;
57	      }
58	      const h: ExecutorHandle = `fake-handle-${input.taskId}-${submittedHandles.length}`;
59	      submittedHandles.push(h);
60	      submittedInputs.push(input);
61	      return h;
62	    },
63	
64	    async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
65	      if (opts?.readResult) return opts.readResult(_handle);
66	      return { terminal_status: "in_review" };
67	    },
68	  };
69	}
70	
71	// ── FakeBriefingTransportPort ─────────────────────────────────────────────────
72	
73	export interface FakeBriefingTransport extends BriefingTransportPort {
74	  readonly putCalls: { handle: ExecutorHandle; content: string }[];
75	  readonly cleanedUpHandles: ExecutorHandle[];
76	}
77	
78	export function createFakeBriefingTransport(): FakeBriefingTransport {
79	  const putCalls: { handle: ExecutorHandle; content: string }[] = [];
80	  const cleanedUpHandles: ExecutorHandle[] = [];
81	
82	  return {
83	    putCalls,
84	    cleanedUpHandles,
85	
86	    async put(handle: ExecutorHandle, content: string): Promise<string> {
87	      putCalls.push({ handle, content });
88	      return `/fake/briefings/${handle}.md`;
89	    },
90	
91	    async cleanup(handle: ExecutorHandle): Promise<void> {
92	      cleanedUpHandles.push(handle);
93	    },
94	  };
95	}
96	
97	// ── FakeWorkflowStatePort ─────────────────────────────────────────────────────
98	
99	export interface FakeWorkflowState extends WorkflowStatePort {
100	  readonly tasks: Map<string, Record<string, unknown>>;
101	  readonly logs: Map<string, Record<string, unknown>[]>;
102	  readonly handles: Map<string, ExecutorHandle>;
103	}
104	
105	export function createFakeWorkflowState(): FakeWorkflowState {
106	  const tasks = new Map<string, Record<string, unknown>>();
107	  const logs = new Map<string, Record<string, unknown>[]>();
108	  const handles = new Map<string, ExecutorHandle>();
109	
110	  function key(
111	    workspaceRoot: string,
112	    featureId: string,
113	    taskId: string,
114	  ): string {
115	    return `${workspaceRoot}:${featureId}:${taskId}`;
116	  }
117	
118	  return {
119	    tasks,
120	    logs,
121	    handles,
122	
123	    async readTask(
124	      workspaceRoot: string,
125	      featureId: string,
126	      taskId: string,
127	    ): Promise<Record<string, unknown>> {
128	      return tasks.get(key(workspaceRoot, featureId, taskId)) ?? {};
129	    },
130	
131	    async writeTask(
132	      workspaceRoot: string,
133	      featureId: string,
134	      taskId: string,
