export type {
  ExecutorHandle,
  HandleKind,
  HandleSubkind,
  HandleMetadata,
  ExecutorCompletion,
  ExecutorPortInput,
  RunnerCallbackPayload,
} from "./types.js";

// ── Port interfaces ───────────────────────────────────────────────────────────
export type {
  ExecutorPort,
  CompletionBrokerPort,
  BriefingTransportPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "./ports.js";

// ── Fake adapters (tests) ─────────────────────────────────────────────────────
export { FakeBrokerAdapter } from "./fake-broker.js";
export { FakeOrchestrator } from "./fake-orchestrator.js";
export type { FakeOrchestratorOpts } from "./fake-orchestrator.js";
export type {
  FakeExecutorPort,
  FakeExecutorPortOpts,
  FakeBriefingTransport,
  FakeWorkflowState,
  FakeWorkspacePull,
  FakeEventEmitter,
  FakeScheduler,
  FakeClock,
} from "./fake-ports.js";
export {
  createFakeExecutorPort,
  createFakeBriefingTransport,
  createFakeWorkflowState,
  createFakeCredential,
  createFakeWorkspacePull,
  createFakeEventEmitter,
  createFakeScheduler,
  createFakeClock,
} from "./fake-ports.js";

